74	@RestController
75	@CrossOrigin(exposedHeaders = "errors, content-type")
76	@RequestMapping("/api")
77	public class OwnerRestControllerV1 implements OwnersApi {
78	
79	    /**
80	     * Dedicated audit logger. On successful owner create an audit line is emitted here carrying
81	     * the newly assigned owner id, customer code, registration date, membership level and
82	     * membership number.
83	     */
84	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
85	
86	    private final ClinicService clinicService;
87	
88	    private final OwnerMapper ownerMapper;
89	
90	    private final PetMapper petMapper;
91	
92	    private final VisitMapper visitMapper;
93	
94	    /** The HTTP request, used to read the optional {@code Idempotency-Key} header on create. */
95	    private final HttpServletRequest request;
96	
97	    /**
98	     * Remembers, per {@code Idempotency-Key}, the id of the owner originally created for that key,
99	     * so a repeated create with an already-seen key returns the original owner instead of creating
100	     * a duplicate.
101	     */
102	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
103	
104	    public OwnerRestControllerV1(ClinicService clinicService,
105	                                 OwnerMapper ownerMapper,
106	                                 PetMapper petMapper,
107	                                 VisitMapper visitMapper,
108	                                 HttpServletRequest request) {
109	        this.clinicService = clinicService;
110	        this.ownerMapper = ownerMapper;
111	        this.petMapper = petMapper;
112	        this.visitMapper = visitMapper;
113	        this.request = request;
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
119	        Collection<Owner> owners;
120	        if (lastName != null) {
121	            owners = this.clinicService.findOwnerByLastName(lastName);
122	        } else {
123	            owners = this.clinicService.findAllOwners();
124	        }
125	        if (owners.isEmpty()) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
134	        Owner owner = this.clinicService.findOwnerById(ownerId);
135	        if (owner == null) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
144	        String idempotencyKey = this.request.getHeader("Idempotency-Key");
145	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
146	            Integer existingId = this.idempotentCreates.get(idempotencyKey);
147	            if (existingId != null) {
148	                Owner existing = this.clinicService.findOwnerById(existingId);
149	                if (existing != null) {
150	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
151	                }
152	            }
153	        }
154	        normalizeAddress(ownerFieldsDto);
155	        validateRequiredFields(ownerFieldsDto);
156	        validatePostcode(ownerFieldsDto);
157	        normalizeTelephone(ownerFieldsDto);
158	        normalizeEmail(ownerFieldsDto);
159	        rejectDuplicateIdentity(ownerFieldsDto);
160	        rejectCityAtCapacity(ownerFieldsDto.getCity());
161	        rejectFutureRegistrationDate(ownerFieldsDto);
162	        defaultRegistrationDate(ownerFieldsDto);
163	        rejectDailyLimit(ownerFieldsDto.getRegistrationDate());
164	        HttpHeaders headers = new HttpHeaders();
165	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
166	        assignCustomerCode(owner);
167	        assignHouseholdId(owner);
168	        assignHouseholdMemberCount(owner);
169	        assignMembershipLevelCap(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
170	        assignNamesakeCount(owner);
171	        assignMembershipNumber(owner);
172	        assignBulkSignupWarning(owner);
173	        assignPossibleDuplicate(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
174	        this.clinicService.saveOwner(owner);
175	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
176	            this.idempotentCreates.put(idempotencyKey, owner.getId());
177	        }
178	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
179	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
180	            owner.getMembershipNumber());
181	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
182	        headers.setLocation(UriComponentsBuilder.newInstance()
183	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
184	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
185	    }
186	
