188	    @Override
189	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
190	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
191	        if (currentOwner == null) {
192	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
193	        }
194	        normalizeEmail(ownerFieldsDto);
195	        currentOwner.setAddress(ownerFieldsDto.getAddress());
196	        currentOwner.setCity(ownerFieldsDto.getCity());
197	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
198	        currentOwner.setLastName(ownerFieldsDto.getLastName());
199	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
200	        currentOwner.setEmail(ownerFieldsDto.getEmail());
201	        this.clinicService.saveOwner(currentOwner);
202	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
203	    }
