236	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
237	    @Override
238	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
239	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
240	        if (currentOwner != null) {
241	            Pet currentPet = this.clinicService.findPetById(petId);
242	            if (currentPet != null) {
243	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
244	                currentPet.setName(petFieldsDto.getName());
245	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
246	                this.clinicService.savePet(currentPet);
247	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
248	            }
249	        }
250	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	    }
252	
253	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
254	    @Override
255	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
256	        HttpHeaders headers = new HttpHeaders();
257	        Visit visit = visitMapper.toVisit(visitFieldsDto);
258	        Pet pet = new Pet();
259	        pet.setId(petId);
260	        visit.setPet(pet);
261	        this.clinicService.saveVisit(visit);
262	        VisitDto visitDto = visitMapper.toVisitDto(visit);
263	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
264	            .buildAndExpand(visit.getId()).toUri());
265	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
266	    }
267	
268	
269	    /**
270	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
271	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
272	     * Validation already rejects {@code null} values and the pattern-constrained fields
273	     * when blank, but {@code address} and {@code city} have no pattern, so a
274	     * whitespace-only value would otherwise slip through.
275	     *
276	     * @param ownerFieldsDto the submitted owner fields
277	     * @throws RequiredFieldsMissingException if any required field is missing or blank
278	     */
279	    /**
280	     * Common street-type abbreviations expanded during address normalization. Keys are the
281	     * upper-cased abbreviation tokens; values are their canonical expansions.
282	     */
283	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
284	        "ST", "STREET",
285	        "RD", "ROAD",
286	        "AVE", "AVENUE");
287	
288	    /**
289	     * Normalizes the submitted address on create, accepting either the structured form
290	     * ({@code addressLine1} plus an optional {@code addressLine2}) or the flat {@code address}
291	     * form retained for backward compatibility. Each supplied field is canonicalized the same way
292	     * (trimmed, internal whitespace collapsed to a single space, upper-cased, and common
293	     * street-type abbreviations expanded — see {@link #ADDRESS_ABBREVIATIONS}), and the normalized
294	     * values are written back onto the request.
295	     *
296	     * <p>The structured fields are preferred when present: when a non-blank {@code addressLine1} is
297	     * supplied, the flat {@code address} is set to the composed value — the normalized
298	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended
299	     * when an {@code addressLine2} is present — otherwise it keeps the normalized flat value. The
300	     * composed {@code address} is therefore persisted, echoed back, and used by everything that
301	     * reads the flat address. A blank/absent value in every form leaves {@code address} blank so the
302	     * required-field check can report it as missing.
303	     *
304	     * @param ownerFieldsDto the submitted owner fields
305	     */
306	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
307	        String addressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
308	        String addressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
309	        String flat = normalizeAddress(ownerFieldsDto.getAddress());
310	        ownerFieldsDto.setAddressLine1(addressLine1);
311	        ownerFieldsDto.setAddressLine2(addressLine2);
312	        String composed;
313	        if (addressLine1 != null && !addressLine1.isBlank()) {
314	            composed = (addressLine2 != null && !addressLine2.isBlank())
315	                ? addressLine1 + " " + addressLine2
316	                : addressLine1;
317	        }
318	        else {
319	            composed = flat;
320	        }
321	        ownerFieldsDto.setAddress(composed);
322	    }
323	
324	    /**
325	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
326	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
327	     * expanded to its full form. A {@code null} value is returned unchanged.
328	     *
329	     * @param raw the address to canonicalize, possibly {@code null}
330	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
331	     */
332	    private static String normalizeAddress(String raw) {
333	        if (raw == null) {
334	            return null;
335	        }
336	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
337	        if (collapsed.isEmpty()) {
338	            return collapsed;
339	        }
340	        String[] tokens = collapsed.split(" ");
341	        StringBuilder sb = new StringBuilder(collapsed.length());
342	        for (int i = 0; i < tokens.length; i++) {
343	            if (i > 0) {
344	                sb.append(' ');
345	            }
346	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
347	        }
348	        return sb.toString();
349	    }
350	
351	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
352	        List<String> errors = new ArrayList<>();
353	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
354	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
355	        requireText("address", ownerFieldsDto.getAddress(), errors);
356	        requireText("city", ownerFieldsDto.getCity(), errors);
357	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
358	        if (!errors.isEmpty()) {
359	            throw new RequiredFieldsMissingException(errors);
360	        }
361	    }
362	
363	    private static void requireText(String field, String value, List<String> errors) {
364	        if (value == null || value.isBlank()) {
365	            errors.add(field);
366	        }
367	    }
368	
369	    /**
370	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
371	     * postcode against the owner's city. A region absent from this table (i.e. a city whose region
372	     * is {@code 'UNKNOWN'}) imposes no range, so any 4-digit postcode is accepted there.
373	     */
374	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
375	        "NSW", new int[] {2000, 2099},
376	        "VIC", new int[] {3000, 3099},
377	        "QLD", new int[] {4000, 4099});
378	
379	    /**
380	     * Validates the submitted {@code postcode} only when present. The field is optional, so a
381	     * {@code null} value is accepted. When present it has already been constrained to four digits
382	     * by Bean Validation; here it is additionally checked against the owner's city: for a city
383	     * whose region is known (see {@link org.springframework.samples.petclinic.mapper.LocalityLookup}),
384	     * the postcode must fall within that region's inclusive range
385	     * ({@link #REGION_POSTCODE_RANGE}); a city with no known region accepts any 4-digit value.
386	     *
387	     * @param ownerFieldsDto the submitted owner fields (city already validated as present)
388	     * @throws InvalidPostcodeException with a 400 status if the postcode is out of range for the
389	     *                                  city's region
390	     */
391	    private static void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
392	        String postcode = ownerFieldsDto.getPostcode();
393	        if (postcode == null) {
394	            return;
395	        }
396	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
397	            .regionFor(ownerFieldsDto.getCity());
398	        int[] range = REGION_POSTCODE_RANGE.get(region);
399	        if (range == null) {
400	            return;
401	        }
402	        int value = Integer.parseInt(postcode);
403	        if (value < range[0] || value > range[1]) {
404	            throw new InvalidPostcodeException(postcode);
405	        }
406	    }
407	
408	    /**
409	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
410	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
411	     * and echoed back in that form.
412	     *
413	     * @param ownerFieldsDto the submitted owner fields
414	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
415	     *                                        valid E.164 number
416	     */
417	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
418	        String e164 = toE164(ownerFieldsDto.getTelephone());
419	        if (e164 == null) {
420	            throw new RequiredFieldsMissingException(List.of("telephone"));
421	        }
422	        ownerFieldsDto.setTelephone(e164);
423	    }
424	
425	    /**
426	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
427	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
428	     * and country code are present they are kept; otherwise country code {@code '+61'} is
429	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
430	     * must contain 8 to 15 digits after the {@code '+'}, and for the recognised country codes
431	     * the national-number length must match the country: {@code '+61'} (Australia) requires
432	     * exactly 9 national digits and {@code '+1'} (NANP) requires exactly 10.
433	     *
434	     * @param raw the submitted telephone, possibly {@code null}
435	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
436	     */
437	    private static String toE164(String raw) {
438	        if (raw == null) {
439	            return null;
440	        }
441	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
442	        String digits;
443	        if (cleaned.startsWith("+")) {
444	            digits = cleaned.substring(1);
445	        } else {
446	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
447	            digits = "61" + national;
448	        }
449	        if (!digits.matches("[0-9]{8,15}")) {
450	            return null;
451	        }
452	        if (digits.startsWith("61")) {
453	            // Australia: exactly 9 national digits after the '+61' country code.
454	            if (digits.length() - 2 != 9) {
455	                return null;
456	            }
457	        } else if (digits.startsWith("1")) {
458	            // NANP: exactly 10 national digits after the '+1' country code.
459	            if (digits.length() - 1 != 10) {
460	                return null;
461	            }
462	        }
463	        return "+" + digits;
464	    }
