476	    /**
477	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
478	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
479	     * the parts may contain whitespace or a second {@code @}.
480	     */
481	    private static final Pattern EMAIL_PATTERN =
482	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
483	
484	    /**
485	     * Disposable email domains that are not accepted for an owner's email. A create whose email
486	     * domain (the part after the {@code '@'}, compared case-insensitively) is on this blocklist is
487	     * rejected. Kept lower-cased to match the normalized email.
488	     */
489	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
490	        "mailinator.com",
491	        "tempmail.com",
492	        "guerrillamail.com");
493	
494	    /**
495	     * Normalizes the submitted email when present: the value is trimmed, required to be a
496	     * syntactically valid address, required not to use a disposable-email domain, and written back
497	     * lower-cased so it is persisted and echoed back in canonical form. A {@code null} email is
498	     * left untouched — the field is optional.
499	     *
500	     * @param ownerFieldsDto the submitted owner fields
501	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically
502	     *                               valid, or its domain is on the disposable-domain blocklist
503	     */
504	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
505	        String email = ownerFieldsDto.getEmail();
506	        if (email == null) {
507	            return;
508	        }
509	        String trimmed = email.strip();
510	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
511	            throw new InvalidEmailException(email);
512	        }
513	        String normalized = trimmed.toLowerCase(Locale.ROOT);
514	        String domain = normalized.substring(normalized.indexOf('@') + 1);
515	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
516	            throw new InvalidEmailException(email);
517	        }
518	        ownerFieldsDto.setEmail(normalized);
519	    }
