522	     * Rejects a create whose supplied {@code registrationDate} is later than the server's current
523	     * date. A registration may be back-dated but never post-dated. The check is made against the
524	     * value as supplied, before any defaulting or business-day roll (see
525	     * {@link #defaultRegistrationDate}); a {@code null} registration date is accepted (it defaults
526	     * to the server date).
527	     *
528	     * @param ownerFieldsDto the submitted owner fields
529	     * @throws FutureRegistrationDateException with a 400 status if the supplied registration date is
530	     *                                         after the server's current date
531	     */
532	    private static void rejectFutureRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
533	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
534	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
535	            throw new FutureRegistrationDateException(supplied);
