539	    /**
540	     * Establishes the effective registration date on create and rolls it onto a business day.
541	     * When the client does not supply a {@code registrationDate} it defaults to the server's
542	     * current date; the resulting date (supplied or defaulted) is then rolled forward to the
543	     * next Monday when it falls on a Saturday or Sunday (see {@link #toBusinessDay}). The
544	     * adjusted value is written back onto the request so it is persisted, echoed back in ISO
545	     * 'YYYY-MM-DD' format, and used by every value derived from the registration date (such as
546	     * the membership number's year segment and the daily create-limit).
547	     *
548	     * @param ownerFieldsDto the submitted owner fields
549	     */
550	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
551	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
552	        if (effective == null) {
553	            effective = LocalDate.now();
554	        }
555	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
556	    }
