558	    /**
559	     * Fixed public holidays that the business-day roll skips. A registration date that lands on
560	     * one of these dates is advanced to the next non-holiday business day (see
561	     * {@link #toBusinessDay}).
562	     */
563	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
564	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
565	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
566	        LocalDate.parse("2026-12-28"));
567	
568	    /**
569	     * Rolls a date forward to the next business day: any date that falls on a Saturday, a Sunday
570	     * or a listed public holiday is advanced one day at a time until it lands on a weekday that is
571	     * not a public holiday; any other date is returned unchanged.
572	     *
573	     * @param date the date to adjust
574	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday
575	     *         business day
576	     */
577	    private static LocalDate toBusinessDay(LocalDate date) {
578	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
579	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
580	            || PUBLIC_HOLIDAYS.contains(date)) {
581	            date = date.plusDays(1);
582	        }
583	        return date;
584	    }
