586	    /**
587	     * Assigns the owner's {@code customerCode} on create, formatted
588	     * {@code '<REGION>-<HASH8>'} where REGION is the region derived from the owner's postcode
589	     * (preferring the postcode range, falling back to the city — the same derivation that yields
590	     * the owner's {@code locality}, see
591	     * {@link org.springframework.samples.petclinic.mapper.LocalityLookup#regionFor(String, String)}),
592	     * and HASH8 is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
593	     * already-normalized (E.164) {@code telephone} concatenated with its {@code lastName} — e.g.
594	     * {@code 'NSW-A1B2C3D4'}. There is no per-city sequence: two owners in the same region share a
595	     * customer code only when their normalized telephone and last name both match.
596	     *
597	     * <p>When the computed customer code collides with an existing owner's {@code customerCode},
598	     * it is de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
599	     * makes it unique among the existing owners, so distinct owners always receive distinct codes.
600	     *
601	     * @param owner the owner being created (with its {@code postcode}, {@code city},
602	     *              {@code telephone} and {@code lastName} already set)
603	     */
604	    private void assignCustomerCode(Owner owner) {
605	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
606	            .regionFor(owner.getPostcode(), owner.getCity());
607	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
608	            .substring(0, 8).toUpperCase(Locale.ROOT);
609	        String base = region + "-" + hash8;
610	        Set<String> existing = this.clinicService.findAllOwners().stream()
611	            .map(Owner::getCustomerCode)
612	            .filter(Objects::nonNull)
613	            .collect(Collectors.toSet());
614	        String customerCode = base;
615	        for (int n = 2; existing.contains(customerCode); n++) {
616	            customerCode = base + "-" + n;
617	        }
618	        owner.setCustomerCode(customerCode);
619	    }
