635	    /**
636	     * Derives the deterministic {@code householdId} for the given {@code lastName} and
637	     * {@code postcode}: the first 12 hex characters of the SHA-256 digest of the normalized
638	     * {@code lastName} (see {@link #collapse}) concatenated with a {@code '|'} and the
639	     * {@code postcode} (empty when absent). Because it is derived purely from those two fields,
640	     * every owner sharing a last name and postcode receives the same value, independent of create
641	     * order. Shared by {@link #assignHouseholdId} (which persists it), {@link #assignHouseholdMemberCount}
642	     * and {@link #assignMembershipLevelCap} (which read the household membership).
643	     *
644	     * @param lastName the owner's last name
645	     * @param postcode the owner's postcode, possibly {@code null}
646	     * @return the derived household id
647	     */
648	    private static String householdIdFor(String lastName, String postcode) {
649	        String key = collapse(lastName) + "|" + (postcode == null ? "" : postcode);
650	        return sha256Hex(key).substring(0, 12);
651	    }
