653	    /**
654	     * Assigns the owner's {@code householdMemberCount} on create: the number of owners in this
655	     * owner's household — those already sharing its {@code householdId} plus this owner itself —
656	     * after this create. Because {@code householdId} is derived from the owner's {@code lastName}
657	     * and {@code postcode} (see {@link #assignHouseholdId}), the count reflects every
658	     * owner registered to the same household, including those who joined via {@code sharesHousehold}.
659	     * The count is taken before this owner is persisted, so it is one more than the number of
660	     * existing household members.
661	     *
662	     * @param owner the owner being created (with its {@code householdId} already assigned)
663	     */
664	    private void assignHouseholdMemberCount(Owner owner) {
665	        String householdId = owner.getHouseholdId();
666	        long existing = this.clinicService.findAllOwners().stream()
667	            .filter(other -> householdId != null && householdId.equals(other.getHouseholdId()))
668	            .count();
669	        owner.setHouseholdMemberCount((int) (existing + 1));
670	    }
