672	    /**
673	     * Assigns the owner's {@code membershipLevelCap} on create, which bounds the level returned by
674	     * {@link org.springframework.samples.petclinic.model.Owner#getMembershipLevel()}. A new owner
675	     * joining an existing household without declaring it (i.e. admitted via its {@code email}, not
676	     * via {@code sharesHousehold}) may not hold a membership level more than one above the current
677	     * maximum membership level among the existing members of its household: the cap is that maximum
678	     * plus one. When the household has no existing member no cap applies, and a declared member
679	     * (one that opted in via {@code sharesHousehold}) is never capped; in both cases the cap is left
680	     * unset so the points-derived level stands. The scan is taken over the existing owners before
681	     * this one is persisted, so it reflects only pre-existing household members.
682	     *
683	     * @param owner the owner being created (with its {@code householdId} already assigned)
684	     * @param declaredHouseholdMember whether the request opted in via {@code sharesHousehold}
685	     */
686	    private void assignMembershipLevelCap(Owner owner, boolean declaredHouseholdMember) {
687	        if (declaredHouseholdMember) {
688	            owner.setMembershipLevelCap(null);
689	            return;
690	        }
691	        String householdId = owner.getHouseholdId();
692	        Integer maxLevel = this.clinicService.findAllOwners().stream()
693	            .filter(other -> !other.isDeleted())
694	            .filter(other -> householdId != null && householdId.equals(other.getHouseholdId()))
695	            .map(Owner::getMembershipLevel)
696	            .filter(Objects::nonNull)
697	            .max(Integer::compareTo)
698	            .orElse(null);
699	        owner.setMembershipLevelCap(maxLevel == null ? null : maxLevel + 1);
700	    }
