760	    /**
761	     * Assigns the owner's soft-match duplicate flags on create. The create has already passed
762	     * {@link #rejectDuplicateIdentity}, so this owner is not a hard duplicate. A declared household
763	     * member (one that opted in via {@code sharesHousehold}) is never flagged: it is an
764	     * acknowledged member of the household, not a suspected duplicate, so {@code possibleDuplicate}
765	     * is {@code false}. Otherwise it is a <em>possible</em> duplicate when an existing owner shares
766	     * its {@code soundex(lastName)} (see {@link Owner#soundex}) and its {@code postcode} but has a
767	     * <em>different</em> {@code identityKey} (so it was not already rejected as a hard duplicate —
768	     * typically a different telephone or email): {@code possibleDuplicate} is set {@code true} and
769	     * {@code possibleDuplicateOf} to that owner's id (the earliest such owner by id when several
770	     * match). Otherwise {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf}
771	     * is left unset. The scan is taken over the existing owners before this one is persisted.
772	     *
773	     * @param owner the owner being created (with its {@code lastName}, {@code postcode},
774	     *              already-normalized {@code telephone} and {@code email} set)
775	     * @param declaredHouseholdMember whether the request opted in via {@code sharesHousehold}
776	     */
777	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
778	        if (declaredHouseholdMember) {
779	            owner.setPossibleDuplicate(false);
780	            owner.setPossibleDuplicateOf(null);
781	            return;
782	        }
783	        String lastName = owner.getLastName();
784	        String postcode = owner.getPostcode();
785	        Integer matchId = null;
786	        if (lastName != null && postcode != null) {
787	            String soundex = Owner.soundex(lastName);
788	            String identityKey = owner.getIdentityKey();
789	            matchId = this.clinicService.findAllOwners().stream()
790	                .filter(existing -> soundex.equals(Owner.soundex(existing.getLastName())))
791	                .filter(existing -> postcode.equals(existing.getPostcode()))
792	                .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
793	                .map(Owner::getId)
794	                .filter(id -> id != null)
795	                .min(Integer::compareTo)
796	                .orElse(null);
797	        }
798	        owner.setPossibleDuplicate(matchId != null);
799	        owner.setPossibleDuplicateOf(matchId);
800	    }
