802	    /**
803	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
804	     *
805	     * @param value the string to hash
806	     * @return the 64-character lower-case hex digest
807	     */
808	    private static String sha256Hex(String value) {
809	        try {
810	            byte[] digest = MessageDigest.getInstance("SHA-256")
811	                .digest(value.getBytes(StandardCharsets.UTF_8));
812	            StringBuilder sb = new StringBuilder(digest.length * 2);
813	            for (byte b : digest) {
814	                sb.append(String.format("%02x", b));
815	            }
816	            return sb.toString();
817	        }
818	        catch (NoSuchAlgorithmException e) {
819	            throw new IllegalStateException("SHA-256 not available", e);
820	        }
821	    }
