823	    /**
824	     * Rejects a create whose whole derived {@code identityKey} already equals that of an existing
825	     * owner (owners flagged deleted are ignored). The key is the SHA-256 hex of
826	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} (see
827	     * {@link Owner#identityKey}), and a create is a duplicate only when its <em>whole</em> key
828	     * matches an existing owner's. Because the telephone is part of the key, two owners sharing a
829	     * last name and postcode but with different telephones have different identity keys and are
830	     * both allowed (the second is flagged a soft match, see {@link #assignPossibleDuplicate}); only
831	     * an exact full-key match is rejected. The submitted telephone and email have already been
832	     * normalized by {@link #normalizeTelephone} and {@link #normalizeEmail}, and each existing
833	     * owner's key is computed the same way so differing input formats collapse to the same value.
834	     *
835	     * @param ownerFieldsDto the submitted owner fields (telephone and email already normalized)
836	     * @throws DuplicateIdentityException with a 409 status if another owner already has the same
837	     *                                    whole identity key
838	     */
839	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
840	        String identityKey = Owner.identityKey(ownerFieldsDto.getTelephone(),
841	            ownerFieldsDto.getEmail(), ownerFieldsDto.getLastName());
842	        boolean duplicate = this.clinicService.findAllOwners().stream()
843	            .filter(owner -> !owner.isDeleted())
844	            .map(Owner::getIdentityKey)
845	            .anyMatch(identityKey::equals);
846	        if (duplicate) {
847	            throw new DuplicateIdentityException(identityKey);
848	        }
849	    }
