899	    /**
900	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
901	     * every internal run of whitespace is collapsed to a single space, and the result is
902	     * lower-cased. A {@code null} value collapses to the empty string.
903	     *
904	     * @param value the value to canonicalize, possibly {@code null}
905	     * @return the collapsed, lower-cased value
906	     */
907	    private static String collapse(String value) {
908	        if (value == null) {
909	            return "";
910	        }
911	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
912	    }
